#!/usr/bin/env node
/**
 * EAST AFRICA CONTRACT — capability register + finding-to-fix ledger.
 *
 * EXTENDS the existing register; it is not a second one. Rows are the 33 capability ids of
 * 02-GLOBAL-CAPABILITY-REGISTRY.json (generated by render.py) plus `extraCapabilities`; the seven
 * contract statuses are DERIVED from that registry by the rules in east-africa/ea-register.source.json
 * and then overridden only where the source cites evidence. Blocker ids are the registry's own.
 *
 * Usage (repo root):  node docs/convergence/tools/ea-register.mjs
 * Writes:             docs/convergence/east-africa/EA-CAPABILITY-REGISTER.{json,md}
 *                     docs/convergence/east-africa/EA-FINDING-LEDGER.md
 * Deterministic: no clock, no network.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const DIR = join(dirname(fileURLToPath(import.meta.url)), '..');
const OUT = join(DIR, 'east-africa');
const registry = JSON.parse(readFileSync(join(DIR, '02-GLOBAL-CAPABILITY-REGISTRY.json'), 'utf8'));
const source = JSON.parse(readFileSync(join(OUT, 'ea-register.source.json'), 'utf8'));

const ALPHA = {
  ALPHA_LIVE: ['YES', 'YES'],
  ASK_BOUND: ['YES', 'UNVERIFIED'],
  RETAINED_ONLY: ['YES', 'UNVERIFIED'],
  COVERAGE_GAP: ['YES', 'UNVERIFIED'],
  PREVIEW_ONLY: ['YES', 'UNVERIFIED'],
  LOCAL_ONLY: ['YES', 'OFF_BY_DEFAULT'],
  DESIGN_ONLY: ['NO', 'N/A'],
  ABSENT: ['NO', 'N/A'],
};
const PRODUCTION = {
  UNVERIFIED_RUNTIME: ['YES', 'UNVERIFIED'],
  COVERAGE_GAP: ['YES', 'UNVERIFIED'],
  ABSENT: ['NO', 'N/A'],
};
const pick = (table, state, id) => {
  const v = table[state];
  if (!v) throw new Error(`${id}: no derivation rule for state ${state}`);
  return v;
};

const rows = registry.capabilities.map((c) => {
  const o = source.overrides[c.id] ?? {};
  const resolved = new Set(o.resolvedOnBranch ?? []);
  const open = (c.blockers ?? []).map((b) => b.id).filter((id) => !resolved.has(id));
  const [aDep, aEn] = pick(ALPHA, c.alphaState, c.id);
  const [pDep, pEn] = pick(PRODUCTION, c.productionState, c.id);
  const absent = c.alphaState === 'ABSENT' || c.alphaState === 'DESIGN_ONLY';
  return {
    id: c.id,
    name: c.name,
    registry: { alphaState: c.alphaState, productionState: c.productionState },
    IMPLEMENTED:
      o.implemented ??
      (absent ? 'NO' : open.length || (o.notImplemented ?? []).length ? 'PARTIAL' : 'YES'),
    TESTED: o.tested ?? 'NOT_ASSESSED',
    DEPLOYED: { alpha: aDep, production: pDep },
    ENABLED: { alpha: aEn, production: pEn },
    LIVE_VERIFIED: {
      alpha: o.liveVerified?.alpha ?? 'NOT_RUN',
      production: o.liveVerified?.production ?? 'NOT_RUN',
    },
    BLOCKED: open,
    RESOLVED_ON_BRANCH_NOT_DEPLOYED: [...resolved],
    NOT_IMPLEMENTED: o.notImplemented ?? [],
    branchDelta: o.branchDelta ?? null,
    evidence: o.evidence ?? null,
  };
});
const known = new Set(rows.map((r) => r.id));
for (const id of Object.keys(source.overrides)) {
  if (!known.has(id)) throw new Error(`override for unknown capability ${id}`);
}

const register = {
  schema: 'ea-capability-register/1',
  contract: source.contract,
  measuredAt: source.measuredAt,
  integrationHead: source.integrationHead,
  outsideThisBranch: source.outsideThisBranch,
  runtimeAuthority: registry.runtime,
  statusVocabulary: source.statusVocabulary,
  derivationRules: source.derivationRules,
  capabilities: rows,
  extraCapabilities: source.extraCapabilities,
};
writeFileSync(join(OUT, 'EA-CAPABILITY-REGISTER.json'), JSON.stringify(register, null, 2) + '\n');

const cell = (s) => String(s).replace(/\|/g, '\\|').replace(/\n/g, ' ');
const count = (f) =>
  rows.reduce((m, r) => ((m[f(r)] = (m[f(r)] ?? 0) + 1), m), {});
const fmt = (m) =>
  Object.entries(m)
    .sort()
    .map(([k, v]) => `${k} ${v}`)
    .join(' · ');

const md = [
  '# East Africa contract — capability register (extends 02)',
  '',
  `Generated by \`tools/ea-register.mjs\` from \`02-GLOBAL-CAPABILITY-REGISTRY.json\` + \`east-africa/ea-register.source.json\`. Measured ${source.measuredAt}. **Do not hand-edit.**`,
  '',
  `**Integration head:** \`${source.integrationHead.branch}\` — ${source.integrationHead.note}`,
  '',
  '**Outside this branch (separate convergence operation):**',
  ...source.outsideThisBranch.map((s) => `- ${s}`),
  '',
  '## Status vocabulary (kept separate — never collapsed into "done")',
  '',
  ...Object.entries(source.statusVocabulary).map(([k, v]) => `- **${k}** — ${v}`),
  '',
  '## Derivation rules',
  '',
  ...source.derivationRules.map((s) => `- ${s}`),
  '',
  '## Totals (33 registry capabilities; denominator = 33)',
  '',
  `- IMPLEMENTED: ${fmt(count((r) => r.IMPLEMENTED))}`,
  `- TESTED: ${fmt(count((r) => r.TESTED))}`,
  `- DEPLOYED alpha: ${fmt(count((r) => r.DEPLOYED.alpha))} · production: ${fmt(count((r) => r.DEPLOYED.production))}`,
  `- ENABLED alpha: ${fmt(count((r) => r.ENABLED.alpha))} · production: ${fmt(count((r) => r.ENABLED.production))}`,
  `- LIVE_VERIFIED alpha: ${fmt(count((r) => r.LIVE_VERIFIED.alpha.split(' ')[0]))} · production: ${fmt(count((r) => r.LIVE_VERIFIED.production))}`,
  `- With open blockers: ${rows.filter((r) => r.BLOCKED.length).length} · with blockers resolved on branch (not deployed): ${rows.filter((r) => r.RESOLVED_ON_BRANCH_NOT_DEPLOYED.length).length}`,
  '',
  '## Register',
  '',
  '| Capability | IMPLEMENTED | TESTED | DEPLOYED α / P | ENABLED α / P | LIVE_VERIFIED α / P | BLOCKED (open) | Resolved on branch, not deployed | NOT_IMPLEMENTED |',
  '|---|---|---|---|---|---|---|---|---|',
  ...rows.map((r) =>
    [
      `**${r.id}**`,
      r.IMPLEMENTED,
      r.TESTED,
      `${r.DEPLOYED.alpha} / ${r.DEPLOYED.production}`,
      `${r.ENABLED.alpha} / ${r.ENABLED.production}`,
      `${r.LIVE_VERIFIED.alpha} / ${r.LIVE_VERIFIED.production}`,
      r.BLOCKED.join(', ') || '—',
      r.RESOLVED_ON_BRANCH_NOT_DEPLOYED.join(', ') || '—',
      r.NOT_IMPLEMENTED.join('; ') || '—',
    ]
      .map(cell)
      .join(' | ')
      .replace(/^/, '| ')
      .concat(' |'),
  ),
  '',
  '## Branch delta and evidence',
  '',
  ...rows
    .filter((r) => r.branchDelta || r.evidence)
    .flatMap((r) => [
      `- **${r.id}** — ${r.branchDelta ?? ''}${r.evidence ? ` _Evidence:_ ${r.evidence}` : ''}`,
    ]),
  '',
  '## Additional register items',
  '',
  ...source.extraCapabilities.flatMap((x) => [
    `### ${x.id}`,
    '',
    `- **Status:** \`${x.status}\``,
    `- **Scope:** ${x.name}`,
    `- **Owner:** ${x.owner}`,
    `- ${x.note}`,
    '',
  ]),
].join('\n');
writeFileSync(join(OUT, 'EA-CAPABILITY-REGISTER.md'), md + '\n');

const ledger = [
  '# East Africa contract — finding-to-fix ledger',
  '',
  `Generated by \`tools/ea-register.mjs\` from \`east-africa/ea-register.source.json\`. Measured ${source.measuredAt}. **Do not hand-edit.**`,
  '',
  'Requirement/finding ids reuse 10-PRODUCTION-BLOCKERS where one exists; `EA-*` ids are additions from the contract. "Deployed" and "Live" never derive from code presence.',
  '',
  '| ID | Requirement / defect | Owner / lane | Commit | Focused test | Broader regression | Migration | Deployed | Live verification | Remaining blocker |',
  '|---|---|---|---|---|---|---|---|---|---|',
  ...source.ledger.map(
    (l) =>
      '| ' +
      [
        `**${l.id}**`,
        l.requirement,
        l.owner,
        l.commit,
        l.focusedTest,
        l.regression,
        l.migration,
        l.deployed,
        l.live,
        l.blocker,
      ]
        .map(cell)
        .join(' | ') +
      ' |',
  ),
  '',
].join('\n');
writeFileSync(join(OUT, 'EA-FINDING-LEDGER.md'), ledger);
console.log(`register: ${rows.length} capabilities + ${source.extraCapabilities.length} extra; ledger: ${source.ledger.length} rows`);
